 'l3-multiply-strategy':[['3.4G'],['3.4G'],['3.5E'],['3.5E'],['3.4G']],
 'l3-shapes':[['3.6A'],['3.6A'],['3.6B'],['3.6B'],['3.6A','3.6B']],
 'l3-area':[['3.6C'],['3.6C'],['3.6D'],['3.6E'],['3.6D']],
